import { Link } from 'react-router-dom';
import { useState, useEffect } from 'react';
import { Menu, X } from 'lucide-react';

export default function Header() {
  const [scrolled, setScrolled] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    window.addEventListener('scroll', onScroll, { passive: true });
    return () => window.removeEventListener('scroll', onScroll);
  }, []);

  const navLinks = [
    { href: '#about', label: 'About' },
    { href: '#contact', label: 'Contact' },
  ];

  return (
    <header
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${
        scrolled
          ? 'bg-background/95 backdrop-blur-md border-b border-white/10'
          : 'bg-transparent'
      }`}
    >
      <div className="container mx-auto px-6 md:px-10">
        <div className="flex h-20 items-center justify-between">
          {/* Monogram logo */}
          <Link to="/" aria-label="Home" className="flex items-center shrink-0">
            <img
              src="/airo-assets/images/logo/primary"
              alt="Monogram"
              className="h-10 w-auto object-contain shrink-0"
            />
          </Link>

          {/* Desktop nav */}
          <nav className="hidden md:flex items-center gap-10">
            {navLinks.map((link) => (
              <a
                key={link.href}
                href={link.href}
                className="relative text-sm tracking-widest uppercase text-foreground/70 hover:text-foreground transition-colors duration-200 group"
              >
                {link.label}
                <span className="absolute -bottom-0.5 left-0 h-px w-0 bg-primary transition-all duration-300 group-hover:w-full" />
              </a>
            ))}
          </nav>

          {/* Mobile toggle */}
          <button
            onClick={() => setMobileOpen(!mobileOpen)}
            className="md:hidden p-2 text-foreground/70 hover:text-foreground transition-colors"
            aria-label="Toggle menu"
          >
            {mobileOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </div>
      </div>

      {/* Mobile menu */}
      {mobileOpen && (
        <div className="md:hidden bg-background/98 backdrop-blur-md border-t border-white/10 px-6 py-6">
          <nav className="flex flex-col gap-6">
            {navLinks.map((link) => (
              <a
                key={link.href}
                href={link.href}
                onClick={() => setMobileOpen(false)}
                className="text-sm tracking-widest uppercase text-foreground/70 hover:text-foreground transition-colors"
              >
                {link.label}
              </a>
            ))}
          </nav>
        </div>
      )}
    </header>
  );
}

export default function Footer() {
  const year = new Date().getFullYear();

  return (
    <footer className="bg-background border-t border-white/10">
      <div className="container mx-auto px-6 md:px-10 py-8">
        <div className="flex flex-col md:flex-row items-center justify-between gap-3">
          <p className="text-xs tracking-widest uppercase text-foreground/40">
            © {year} Alex Morgan. All rights reserved.
          </p>
          <p className="text-xs tracking-widest uppercase text-foreground/30">
            Designed &amp; Built with care
          </p>
        </div>
      </div>
    </footer>
  );
}

import { Helmet } from '@dr.pogodin/react-helmet';
import { motion } from 'motion/react';
import { Github, Linkedin, Twitter, Instagram, ArrowDown, Mail } from 'lucide-react';

// ── Subtle dot-grid SVG background ──────────────────────────────────────────
function DotGrid() {
  return (
    <svg
      className="absolute inset-0 w-full h-full opacity-[0.06] pointer-events-none"
      xmlns="http://www.w3.org/2000/svg"
    >
      <defs>
        <pattern id="dots" x="0" y="0" width="28" height="28" patternUnits="userSpaceOnUse">
          <circle cx="1.5" cy="1.5" r="1.5" fill="currentColor" />
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#dots)" />
    </svg>
  );
}

// ── Decorative geometric accent for About section ────────────────────────────
function GeometricAccent() {
  return (
    <div className="relative flex items-center justify-center w-full h-full min-h-[320px]">
      {/* Outer ring */}
      <div className="absolute w-64 h-64 rounded-full border border-primary/20" />
      {/* Middle ring */}
      <div className="absolute w-44 h-44 rounded-full border border-primary/30" />
      {/* Inner square rotated */}
      <div className="absolute w-28 h-28 border border-primary/40 rotate-45" />
      {/* Center initial */}
      <span
        className="relative z-10 text-7xl font-heading font-bold text-primary/30 select-none"
        aria-hidden="true"
      >
        A
      </span>
      {/* Thin horizontal line through center */}
      <div className="absolute w-72 h-px bg-gradient-to-r from-transparent via-primary/30 to-transparent" />
    </div>
  );
}

// ── Fade-up animation variant ────────────────────────────────────────────────
const fadeUp = {
  hidden: { opacity: 0, y: 24 },
  visible: (delay = 0) => ({
    opacity: 1,
    y: 0,
    transition: { duration: 0.5, delay, ease: 'easeOut' as const },
  }),
};

const fadeIn = {
  hidden: { opacity: 0, y: 16 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.4, ease: 'easeOut' as const },
  },
};

// ── Social links ─────────────────────────────────────────────────────────────
const socials = [
  { icon: Github, href: 'https://github.com', label: 'GitHub' },
  { icon: Linkedin, href: 'https://linkedin.com', label: 'LinkedIn' },
  { icon: Twitter, href: 'https://twitter.com', label: 'Twitter / X' },
  { icon: Instagram, href: 'https://instagram.com', label: 'Instagram' },
];

// ── Skills list ──────────────────────────────────────────────────────────────
const skills = [
  'UI / UX Design',
  'React & TypeScript',
  'Motion & Interaction',
  'Brand Identity',
  'Design Systems',
  'Creative Direction',
];

export default function HomePage() {
  return (
    <>
      <Helmet>
        <title>Alex Morgan — Creative Developer & Designer</title>
        <meta
          name="description"
          content="Personal portfolio of Alex Morgan — a creative developer and designer crafting thoughtful digital experiences."
        />
      </Helmet>

      {/* ── HERO ──────────────────────────────────────────────────────────── */}
      <section className="relative min-h-screen flex flex-col items-center justify-center overflow-hidden bg-background text-foreground">
        <DotGrid />

        {/* Subtle radial glow */}
        <div className="absolute inset-0 pointer-events-none">
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] rounded-full bg-primary/5 blur-[120px]" />
        </div>

        <div className="relative z-10 container mx-auto px-6 md:px-10 text-center">
          {/* Eyebrow label */}
          <motion.p
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0}
            className="text-xs tracking-[0.3em] uppercase text-primary mb-6"
          >
            Portfolio
          </motion.p>

          {/* Name — oversized typographic statement */}
          <motion.h1
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0.1}
            className="font-heading font-bold leading-none tracking-tight text-foreground mb-6"
            style={{ fontSize: 'clamp(3.5rem, 10vw, 9rem)' }}
          >
            Alex Morgan
          </motion.h1>

          {/* Thin rule */}
          <motion.div
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0.25}
            className="mx-auto w-16 h-px bg-primary/60 mb-6"
          />

          {/* Tagline */}
          <motion.p
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0.3}
            className="text-sm md:text-base tracking-[0.2em] uppercase text-foreground/60 max-w-md mx-auto"
          >
            Creative Developer &amp; Designer
          </motion.p>

          {/* CTA */}
          <motion.div
            variants={fadeUp}
            initial="hidden"
            animate="visible"
            custom={0.45}
            className="mt-12"
          >
            <a
              href="#about"
              className="inline-flex items-center gap-2 text-xs tracking-widest uppercase text-foreground/50 hover:text-primary transition-colors duration-200 group"
            >
              View My Work
              <ArrowDown
                size={14}
                className="group-hover:translate-y-1 transition-transform duration-200"
              />
            </a>
          </motion.div>
        </div>

        {/* Bottom scroll indicator */}
        <motion.div
          variants={fadeUp}
          initial="hidden"
          animate="visible"
          custom={0.6}
          className="absolute bottom-10 left-1/2 -translate-x-1/2 flex flex-col items-center gap-2"
        >
          <div className="w-px h-12 bg-gradient-to-b from-transparent to-primary/40" />
        </motion.div>
      </section>

      {/* ── ABOUT ─────────────────────────────────────────────────────────── */}
      <section id="about" className="bg-background py-28 md:py-36">
        {/* Section rule */}
        <div className="container mx-auto px-6 md:px-10">
          <div className="w-full h-px bg-white/10 mb-20" />

          <motion.div
            variants={fadeIn}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            className="grid grid-cols-1 md:grid-cols-2 gap-16 md:gap-24 items-center"
          >
            {/* Left — text */}
            <div>
              <p className="text-xs tracking-[0.3em] uppercase text-primary mb-6">About Me</p>
              <h2 className="font-heading text-4xl md:text-5xl font-bold text-foreground mb-8 leading-tight">
                Crafting experiences that feel as good as they look.
              </h2>
              <div className="space-y-5 text-foreground/60 leading-relaxed">
                <p>
                  I'm a creative developer and designer with over eight years of experience
                  building digital products that sit at the intersection of design and engineering.
                  My work spans brand identity, interactive interfaces, and design systems for
                  startups and established companies alike.
                </p>
                <p>
                  I believe the best digital experiences are born from obsessive attention to
                  detail — the kind that users feel but can't quite name. Whether I'm writing
                  TypeScript or crafting a motion system, I bring the same deliberate care to
                  every layer of the stack.
                </p>
                <p>
                  When I'm not at the keyboard, you'll find me exploring architecture, reading
                  about typography, or hunting for the perfect espresso.
                </p>
              </div>

              {/* Skills grid */}
              <div className="mt-10 grid grid-cols-2 gap-3">
                {skills.map((skill) => (
                  <div key={skill} className="flex items-center gap-2">
                    <span className="w-1 h-1 rounded-full bg-primary shrink-0" />
                    <span className="text-xs tracking-wider uppercase text-foreground/50">
                      {skill}
                    </span>
                  </div>
                ))}
              </div>
            </div>

            {/* Right — decorative geometric */}
            <div className="hidden md:flex items-center justify-center">
              <GeometricAccent />
            </div>
          </motion.div>
        </div>
      </section>

      {/* ── CONTACT ───────────────────────────────────────────────────────── */}
      <section id="contact" className="bg-background py-28 md:py-36">
        <div className="container mx-auto px-6 md:px-10">
          <div className="w-full h-px bg-white/10 mb-20" />

          <motion.div
            variants={fadeIn}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
            className="max-w-2xl"
          >
            <p className="text-xs tracking-[0.3em] uppercase text-primary mb-6">Contact</p>
            <h2 className="font-heading text-4xl md:text-6xl font-bold text-foreground mb-8 leading-tight">
              Get In Touch
            </h2>
            <p className="text-foreground/60 leading-relaxed mb-12 max-w-lg">
              Whether you have a project in mind, a question, or just want to say hello — my inbox
              is always open.
            </p>

            {/* Email link */}
            <a
              href="mailto:hello@alexmorgan.design"
              className="group inline-flex items-center gap-3 text-foreground hover:text-primary transition-colors duration-200 mb-14"
            >
              <Mail size={18} className="text-primary shrink-0" />
              <span className="relative text-lg tracking-wide">
                hello@alexmorgan.design
                <span className="absolute -bottom-0.5 left-0 h-px w-0 bg-primary transition-all duration-300 group-hover:w-full" />
              </span>
            </a>

            {/* Social icons */}
            <div className="flex items-center gap-6">
              {socials.map(({ icon: Icon, href, label }) => (
                <a
                  key={label}
                  href={href}
                  target="_blank"
                  rel="noopener noreferrer"
                  aria-label={label}
                  className="text-foreground/40 hover:text-primary transition-all duration-150 hover:scale-110"
                >
                  <Icon size={20} />
                </a>
              ))}
            </div>
          </motion.div>
        </div>
      </section>
    </>
  );
}

